module.exports = function(RED) {
    "use strict";

    var INT16_MIN = -32768;
    var INT16_MAX = 32767;

    function MeoCommandNode(n) {
        RED.nodes.createNode(this, n);
        var node = this;
        node.edge = RED.nodes.getNode(n.edge);
        node.device = n.device;
        node.cap = n.cap;
        node.op = n.op === "read" ? "read" : "write";
        node.value = n.value;
        node.valueType = n.valueType || "msg";

        node.on("input", function(msg, send, done) {
            if (!node.edge) {
                fail(node, done, "meo.errors.noEdge");
                return;
            }
            if (!node.device) {
                fail(node, done, "meo.errors.noDevice");
                return;
            }
            if (typeof node.cap !== "string" || !node.cap) {
                fail(node, done, "meo.errors.noCap");
                return;
            }

            // Only writes carry a value; the edge ignores it for reads.
            if (node.op === "read") {
                sendCommand(node, msg, send, done, 0);
                return;
            }
            RED.util.evaluateNodeProperty(node.value, node.valueType, node, msg, function(err, value) {
                if (err) {
                    fail(node, done, "meo.errors.badValue", err);
                    return;
                }
                var scalar = toInt16(value);
                if (scalar === null) {
                    fail(node, done, "meo.errors.badValue",
                        new Error(RED._("meo.errors.notInt16", { value: String(value) })));
                    return;
                }
                sendCommand(node, msg, send, done, scalar);
            });
        });
    }

    function sendCommand(node, msg, send, done, value) {
        node.status({ fill: "blue", shape: "dot", text: "node-red:meo.status.sending" });

        node.edge.sendCommand(node.device, node.cap, node.op, value).then(function(replyValue) {
            msg.payload = replyValue;
            msg.deviceId = node.device;
            msg.cap = node.cap;
            node.status({ fill: "green", shape: "dot", text: String(replyValue) });
            send(msg);
            done();
        }).catch(function(err) {
            node.status({ fill: "red", shape: "ring", text: err.message });
            done(err);
        });
    }

    // The frame carries an int16. Booleans are the common inject payload for an
    // on/off actuator, so treat them as 1/0 rather than rejecting them.
    function toInt16(value) {
        if (typeof value === "boolean") { return value ? 1 : 0; }
        if (value === null || value === undefined || value === "") { return null; }
        var number = Math.round(Number(value));
        if (!isFinite(number) || number < INT16_MIN || number > INT16_MAX) { return null; }
        return number;
    }

    // Status text is resolved by the editor, so it carries the namespace;
    // the error message is resolved here and does not.
    function fail(node, done, key, err) {
        node.status({ fill: "red", shape: "ring", text: "node-red:" + key });
        done(new Error(err ? err.message : RED._(key)));
    }

    RED.nodes.registerType("meo-command", MeoCommandNode);
};
